export function getOpenPaperAccountInstruction<
  TAccountAuthority extends string,
  TAccountPaper extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof RESULT_REGISTRY_PROGRAM_ADDRESS,
>(
  input: OpenPaperAccountInput<
    TAccountAuthority,
    TAccountPaper,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress },
): OpenPaperAccountInstruction<
  TProgramAddress,
  TAccountAuthority,
  TAccountPaper,
  TAccountSystemProgram
> {
  // Program address.
  const programAddress =
    config?.programAddress ?? RESULT_REGISTRY_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    authority: { value: input.authority ?? null, isWritable: true },
    paper: { value: input.paper ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.authority),
      getAccountMeta(accounts.paper),
      getAccountMeta(accounts.systemProgram),
    ],
    data: getOpenPaperAccountInstructionDataEncoder().encode(
      args as OpenPaperAccountInstructionDataArgs,
    ),
    programAddress,
  } as OpenPaperAccountInstruction<
    TProgramAddress,
    TAccountAuthority,
    TAccountPaper,
    TAccountSystemProgram
  >);
}

